# Re-analyzing the demo very carefully with proper tracking

input_grid = [
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 6, 4, 4, 4, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 4, 4, 4, 4, 0, 4, 4, 4, 4, 6, 4, 4, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4]
]

output_grid = [
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 6, 4, 4, 4, 6, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 4, 4, 4, 0, 4, 4, 4, 4, 4, 6, 4, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4]
]

# List all positions of each color
from collections import defaultdict

def find_positions(grid, color):
    positions = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == color:
                positions.append((r, c))
    return positions

print("Color 0 positions in INPUT:")
for p in find_positions(input_grid, 0):
    print(f"  {p}")

print("\nColor 0 positions in OUTPUT:")
for p in find_positions(output_grid, 0):
    print(f"  {p}")

print("\nColor 6 positions in INPUT:")
for p in find_positions(input_grid, 6):
    print(f"  {p}")

print("\nColor 6 positions in OUTPUT:")
for p in find_positions(output_grid, 6):
    print(f"  {p}")

# Check delta for each color 0 position
print("\nColor 0 deltas:")
for inp_r, inp_c in find_positions(input_grid, 0):
    out_row = output_grid[inp_r]
    # Find corresponding 0 in output
    for out_c in range(inp_c - 2, len(out_row)):
        if out_row[out_c] == 0:
            print(f"  ({inp_r}, {inp_c}) -> ({inp_r}, {out_c}): delta={out_c-inp_c}")
            break

# Check delta for each color 6 position
print("\nColor 6 deltas:")
for inp_r, inp_c in find_positions(input_grid, 6):
    out_row = output_grid[inp_r]
    for out_c in range(inp_c - 2, len(out_row)):
        if out_row[out_c] == 6:
            print(f"  ({inp_r}, {inp_c}) -> ({inp_r}, {out_c}): delta={out_c-inp_c}")
            break

# Direct comparison between input and output for each row

input_grid = [
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 6, 4, 4, 4, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 0, 4, 4, 4, 4, 0, 4, 4, 4, 4, 6, 4, 4, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4]
]

output_grid = [
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 6, 4, 4, 4, 6, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 4, 4, 4, 0, 4, 4, 4, 4, 4, 6, 4, 6, 4, 4, 4, 4, 4, 4, 4],
    [4, 4, 4, 4, 4, 4, 4, 0, 0, 0, 0, 0, 4, 4, 4, 4, 4, 6, 6, 6, 6, 4, 4, 4, 4, 4, 4]
]

print("Row-by-row comparison:")
for r in range(5):
    inp_row = input_grid[r]
    out_row = output_grid[r]
    differences = []
    for c in range(len(inp_row)):
        if inp_row[c] != out_row[c]:
            differences.append((c, inp_row[c], out_row[c]))
    print(f"Row {r}:")
    if differences:
        for c, i, o in differences:
            if i == 0:
                print(f"  Col {c}: 0 -> {o}")
            elif i == 6:
                print(f"  Col {c}: 6 -> {o}")
    else:
        print(f"  No changes")

# Now check column shifts more carefully
print("\n\nDetailed column position changes for color 0:")
for r in range(5):
    for c in range(27):
        if input_grid[r][c] == 0:
            shifted_c = c + 1
            if shifted_c < 27:
                if output_grid[r][shifted_c] == 0:
                    print(f"  ({r},{c}): stayed at shifted pos {shifted_c}")
                else:
                    print(f"  ({r},{c}): expected {shifted_c} but got {output_grid[r][shifted_c]}")

# Request another demo pair to understand the full transformation

print("Requesting second demo pair...")
